import{renderCustomModel,renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{renalFigure}from './renal-figures.js?v=20261023-physicscomplete01';import{buildRenal}from './renal-meshes.js?v=20261023-physicscomplete01';
export function showRenal(spec='filter',w={}){let[k,s]=spec.split(':'),state=k==='osmosis'?(s==='1'?'concentrated':s==='2'?'equal':'dilute'):k==='adh'&&s==='2'?'high-water':'low-water',o={kind:k,state,progress:1,...w},title=w.title||({osmosis:'Water and cell volume',filter:'Filtration and selective recovery',urea:'Liver production, kidney removal',adh:'ADH and water permeability',dialysis:'Exchange without mixing',ledger:'Read the supplied amounts',treatments:'Compare treatment evidence',losses:'Where substances leave the body'})[k],figure=renalFigure(o);if(['ledger','losses','treatments'].includes(k)||o.concealed||o.state==='matched'){renderDiagram(title,w.label||'Original schematic or supplied evidence',figure,'WATER AND NITROGEN BALANCE');return;}renderCustomModel({name:title,formula:w.label||'Functional compartments · use the labelled diagram',kicker:'FUNCTIONAL MODEL',aria:title+'. Schematic compartments; not required nephron anatomy.',atoms:[],bonds:[],radius:2.35,viewKey:'renal-'+k,startPaused:true,note:'Symbolic scale, rates and amounts · not clinical measurements',diagram:figure,build:(g,T)=>buildRenal(g,T,o)});}
